          ) : null}

          {/* 编辑时：平台管理员可改角色/店铺 */}
          {editing && isPlatformAdmin ? (
            <>
              <Form.Item name="role" label="角色" rules={[{ required: true }]}>
                <Select
                  options={[
                    { label: '顾客', value: 'customer' },
                    { label: '商家', value: 'merchant' },
                    { label: '平台管理员', value: 'admin' },
                    { label: '骑手', value: 'rider' },
