                extra="商家必须绑定店铺；平台管理员请留空"
              >
                <Select
                  allowClear
                  placeholder="留空 = 平台管理员 / 无绑定"
                  options={shops.map((s) => ({ label: s.name, value: s.id }))}
                  showSearch
                  optionFilterProp="label"
                />
